for(i=0; i<4; i++){
for(j=0; j<8; j++)
{
if(j==0) cout<<endl;
            cout<<p[i][j]<<"\t";
        }
}
//开始释放申请的堆
for(i=0; i<4; i++){
delete [] p[i];
    }
delete [] p;
    return 0;
}
```

```cpp
三维数组

int ***array;
// 假定数组第一维为 m， 第二维为 n， 第三维为h
// 动态分配空间
array = new int **[m];
for( int i=0; i<m; i++ )
{
array[i] = new int *[n];
    for( int j=0; j<n; j++ )
{
array[i][j] = new int [h];
    }
}
//释放
for( int i=0; i<m; i++ )
{
for( int j=0; j<n; j++ )
{
delete[] array[i][j];
    }
delete[] array[i];
}
delete[] array;
```

