//输出 p[i][j][k] 三维数据
for(i=0; i<2; i++)
{
for(j=0; j<3; j++)
{
for(k=0;k<4;k++)
{
p[i][j][k]=i+j+k;
                cout<<p[i][j][k]<<" ";
            }
cout<<endl;
        }
cout<<endl;
    }
// 释放内存
for(i=0; i<2; i++)
{
for(j=0; j<3; j++)
{
delete [] p[i][j];
        }
}
for(i=0; i<2; i++)
{
delete [] p[i];
    }
delete [] p;
    return 0;
}
```

## 对象的动态内存分配

对象与简单的数据类型没有什么不同。例如，请看下面的代码，我们将使用一个对象数组来理清这一概念：

```cpp
#include <iostream>
using namespace std;

class Box
{
public:
      Box() {
cout << "调用构造函数！" <<endl;
      }
      ~Box() {
cout << "调用析构函数！" <<endl;
      }
};

int main( )
{
Box* myBoxArray = new Box[4];

   delete [] myBoxArray; // 删除数组
return 0;
}
```

如果要为一个包含四个 Box 对象的数组分配内存，构造函数将被调用 4 次，同样地，当删除这些对象时，析构函数也将被调用相同的次数（4次）。

当上面的代码被编译和执行时，它会产生下列结果：

```bash
调用构造函数！
调用构造函数！
调用构造函数！
调用构造函数！
调用析构函数！
调用析构函数！
调用析构函数！
调用析构函数！
```

