    char buffer[50];
    int value = 42;
    sprintf(buffer, "Value: %d", value); // 输出到字符串

    int readValue;
    sscanf(buffer, "Value: %d", &readValue); // 从字符串读取

    return 0;
}
```

### fgets 和 fputs

用于从文件中读取字符串和写入字符串到文件。

```cpp
#include <cstdio>

int main() {
    FILE* file = fopen("example.txt", "r");
    if (file) {
        char buffer[100];
        if (fgets(buffer, sizeof(buffer), file)) {
            // 读取成功
        }
        fclose(file);
    }

    file = fopen("example.txt", "w");
    if (file) {
        fputs("Hello, World!\n", file); // 写入字符串到文件
        fclose(file);
    }
    return 0;
}
```

### getc 和 putc

用于从文件中读取字符和写入字符到文件。

```cpp
#include <cstdio>

int main() {
    FILE* file = fopen("example.txt", "r");
    if (file) {
        int c = getc(file); // 读取一个字符
        fclose(file);
    }

    file = fopen("example.txt", "w");
    if (file) {
        putc('A', file); // 写入一个字符
        fclose(file);
    }
    return 0;
}
```

### feof 和 ferror

用于检测文件结束和文件错误。

```cpp
#include <cstdio>

int main() {
    FILE* file = fopen("example.txt", "r");
    if (file) {
        while (!feof(file)) {
            int c = getc(file);
            if (ferror(file)) {
                // 处理错误
                break;
            }
            // 处理字符
        }
        fclose(file);
    }
    return 0;
}
```

### EOF

表示文件结束标志。

```cpp
#include <cstdio>

int main() {
    FILE* file = fopen("example.txt", "r");
    if (file) {
        int c;
        while ((c = getc(file)) != EOF) {
            // 处理字符
        }
        fclose(file);
    }
    return 0;
}
```

### NULL

表示空指针。

```cpp
#include <cstdio>

int main() {
    FILE* file = fopen("example.txt", "r");
    if (file == NULL) {
        // 处理文件打开错误
    } else {
        fclose(file);
    }
    return 0;
}
```

