    int num1 = std::atoi(str1.c_str()); // 将字符串转换为整数
    double num2 = std::atof(str2.c_str()); // 将字符串转换为浮点数

    std::cout << "Integer: " << num1 << std::endl;
    std::cout << "Float: " << num2 << std::endl;
    return 0;
}
```

输出结果：

```bash
Integer: 123
Float: 456.78
```

